from pwn import *
import json
import subprocess

def run_r2_cmd(binary, cmd):
    r2_proc = subprocess.run(['r2', '-q', '-c', cmd, binary], capture_output=True, text=True)
    return r2_proc.stdout.strip()

def get_tree_node(addr):
    # Structure analysis using radare2
    # Get node contents at addr
    node_data = run_r2_cmd('./ctf_files/rabbithole', f'pxw 32@{addr}')

    try:
        lines = node_data.split('\n')
        values = []
        for line in lines:
            if '0x' in line:
                parts = line.split()
                if len(parts) >= 2:
                    values.extend([int(x, 16) for x in parts[1:5]])

        if len(values) < 8:
            return None

        return {
            'is_leaf': bool(values[0] & 0xff),
            'lower_bound': values[2] & 0xff,
            'upper_bound': (values[2] >> 8) & 0xff,
            'left': values[4] if values[4] != 0 else None,
            'right': values[6] if values[6] != 0 else None
        }
    except:
        return None

def analyze_tree(root_addr, depth=0, visited=None):
    if visited is None:
        visited = set()

    if root_addr in visited or root_addr == 0 or depth > 15:
        return None

    visited.add(root_addr)

    node = get_tree_node(root_addr)
    if not node:
        return None

    result = {
        'addr': hex(root_addr),
        'is_leaf': node['is_leaf'],
        'range': (
            chr(node['lower_bound']) if 32 <= node['lower_bound'] <= 126 else hex(node['lower_bound']),
            chr(node['upper_bound']) if 32 <= node['upper_bound'] <= 126 else hex(node['upper_bound'])
        ),
        'children': []
    }

    if node['left']:
        left = analyze_tree(node['left'], depth + 1, visited)
        if left:
            result['children'].append(('left', left))

    if node['right']:
        right = analyze_tree(node['right'], depth + 1, visited)
        if right:
            result['children'].append(('right', right))

    return result

def print_tree(tree, depth=0):
    if not tree:
        return

    indent = '  ' * depth
    print(f"{indent}Node @ {tree['addr']}:")
    print(f"{indent}Is Leaf: {tree['is_leaf']}")
    print(f"{indent}Valid Range: {tree['range'][0]} - {tree['range'][1]}")

    for direction, child in tree['children']:
        print(f"{indent}{direction.capitalize()} branch:")
        print_tree(child, depth + 1)

def main():
    print("Analyzing binary...")

    # Initialize r2
    init_cmd = 'aaa; afl'  # Analyze all functions
    run_r2_cmd('./ctf_files/rabbithole', init_cmd)

    # Get roots array address
    roots_cmd = 'fs symbols; f~roots'
    roots_info = run_r2_cmd('./ctf_files/rabbithole', roots_cmd)

    try:
        roots_addr = int(roots_info.split()[0], 16)
    except:
        print("Error: Could not find roots array")
        return

    print(f"Found roots array at {hex(roots_addr)}")

    # Get roots array data
    roots_data_cmd = f'pxq 64@{roots_addr}'  # Get first 8 root pointers
    roots_data = run_r2_cmd('./ctf_files/rabbithole', roots_data_cmd)

    roots = []
    try:
        for line in roots_data.split('\n'):
            if '0x' in line:
                parts = line.split()
                if len(parts) >= 2:
                    addr = int(parts[1], 16)
                    if addr != 0:
                        roots.append(addr)
    except:
        print("Error parsing roots array")
        return

    print(f"Found {len(roots)} root nodes")
    print("Analyzing tree structures...")
    print("-" * 60)

    # Analyze first few trees as example
    valid_ranges = []
    for i, root in enumerate(roots[:5]):  # Analyze first 5 trees
        if root and root != 0:
            print(f"\nAnalyzing tree {i}:")
            tree = analyze_tree(root)
            if tree:
                print_tree(tree)
                valid_ranges.append((i, tree['range']))

    print("\nValid character ranges summary:")
    print("-" * 60)
    for pos, (lower, upper) in valid_ranges:
        print(f"Position {pos}: {lower} - {upper}")

if __name__ == "__main__":
    main()

