#!/usr/bin/env python3
from pwn import *

class Node:
    def __init__(self, addr, data):
        self.addr = addr
        self.is_leaf = data[0] == 1
        self.lower = data[8]
        self.upper = data[9]
        self.left = u64(data[0x10:0x18])
        self.right = u64(data[0x18:0x20])

def read_node(elf, addr):
    if addr == 0:
        return None
    data = elf.read(addr, 0x20)
    return Node(addr, data)

def traverse_tree(elf, node_addr, valid_chars):
    if node_addr == 0:
        return

    node = read_node(elf, node_addr)
    if node is None:
        return

    if node.is_leaf:
        for c in range(node.lower, node.upper + 1):
            valid_chars.add(c)

    traverse_tree(elf, node.left, valid_chars)
    traverse_tree(elf, node.right, valid_chars)

def analyze_trees():
    binary = "./ctf_files/rabbithole"
    elf = ELF(binary)

    # Get roots array
    roots_addr = elf.symbols['roots']
    num_positions = 0x3b  # 59 positions from main function

    print("[*] Analyzing all binary search trees...")
    valid_chars_per_pos = []

    for i in range(num_positions):
        root_ptr = u64(elf.read(roots_addr + i*8, 8))
        if root_ptr == 0:
            continue

        valid_chars = set()
        traverse_tree(elf, root_ptr, valid_chars)

        # Convert to printable chars
        printable = sorted([chr(c) for c in valid_chars if 32 <= c <= 126])
        valid_chars_per_pos.append(printable)

        # Print analysis
        print(f"\nPosition {i:2d}:")
        print("-" * 40)
        print(f"Valid chars: {''.join(printable)}")
        print(f"Total valid chars: {len(printable)}")

