#!/usr/bin/env python3
from pwn import *

class Node:
    def __init__(self, addr, data):
        self.addr = addr
        self.is_leaf = data[0] == 1
        self.lower = data[8]
        self.upper = data[9]
        self.left = u64(data[0x10:0x18]) if data[0x10:0x18] != b'\x00'*8 else 0
        self.right = u64(data[0x18:0x20]) if data[0x18:0x20] != b'\x00'*8 else 0

def read_node(elf, base, addr):
    if addr == 0:
        return None
    try:
        data = elf.read(base + (addr & ((1 << 64) - 1)), 0x20)
        return Node(addr, data)
    except Exception as e:
        print(f"Error reading node at {hex(addr)}: {e}")
        return None

def traverse_tree(elf, base, node_addr, valid_chars):
    if node_addr == 0:
        return

    node = read_node(elf, base, node_addr)
    if node is None:
        return

    if node.is_leaf:
        for c in range(node.lower, node.upper + 1):
            valid_chars.add(c)
    else:
        traverse_tree(elf, base, node.left, valid_chars)
        traverse_tree(elf, base, node.right, valid_chars)

def get_base_address():
    # Use GDB to get the base address
    cmd = """gdb -q -nx ./ctf_files/rabbithole -ex "start" -ex "p/x &roots" -ex "quit" """
    r = process(cmd.split())
    output = r.recvall().decode()
    r.close()

    # Parse the base address
    for line in output.split('\n'):
        if '=' in line:
            addr = int(line.split('=')[1].strip(), 16)
            return addr & ~0xfff  # Page align
    return 0

def analyze_trees():
    binary = "./ctf_files/rabbithole"
    elf = ELF(binary)

    base_addr = get_base_address()
    print(f"[*] Base address: {hex(base_addr)}")

    # Get roots array
    roots_offset = elf.symbols['roots']
    roots_addr = base_addr + roots_offset
    num_positions = 0x3b  # 59 positions from main function

    print("[*] Analyzing all binary search trees...")
    valid_chars_per_pos = []

    for i in range(num_positions):
        try:
            root_ptr = u64(elf.read(roots_addr + i*8, 8))
            if root_ptr == 0:
                valid_chars_per_pos.append([])
                continue

            valid_chars = set()
            traverse_tree(elf, base_addr, root_ptr, valid_chars)

            # Convert to printable chars
            printable = sorted([chr(c) for c in valid_chars if 32 <= c <= 126])
            valid_chars_per_pos.append(printable)

            # Print analysis
            print(f"\nPosition {i:2d}:")
            print("-" * 40)
            print(f"Valid chars: {''.join(printable)}")
            print(f"Total valid chars: {len(printable)}")

            # Check for flag patterns
            patterns = []
            if 'f' in printable and i == 0:
                patterns.append("Possible 'flag{' start")
            if '{' in printable and i == 4:
                patterns.append("Possible '{' position")
            if '}' in printable:
                patterns.append("Contains closing brace")

            if patterns:
                print("Patterns found:", ", ".join(patterns))

        except Exception as e:
            print(f"Error processing position {i}: {e}")
            valid_chars_per_pos.append([])

    # Analyze overall patterns
    print("\n[*] Overall Analysis:")
    print("=" * 60)

    # Look for positions with very limited choices
    print("\nPositions with limited choices:")
    for i, chars in enumerate(valid_chars_per_pos):
        if 0 < len(chars) < 5:
            print(f"Position {i:2d}: {''.join(chars)} ({len(chars)} choices)")

    # Check for consistent character types
    print("\nCharacter type analysis:")
    for i, chars in enumerate(valid_chars_per_pos):
        if not chars:
            continue
        types = set()
        if any(c.isalpha() for c in chars):
            types.add("letters")
        if any(c.isdigit() for c in chars):
            types.add("digits")
        if any(c in '_{}' for c in chars):
            types.add("special")
        print(f"Position {i:2d}: {', '.join(types)}")

    return valid_chars_per_pos

if __name__ == "__main__":
    analyze_trees()

