#!/usr/bin/env python3
from pwn import *
import string

context.log_level = 'error'

def extract_byte_range(data, addr, size=1):
    try:
        return data[addr:addr + size]
    except:
        return b'\x00' * size

def analyze_node(binary, base_addr, visited=None):
    if visited is None:
        visited = set()

    if base_addr in visited or base_addr == 0:
        return set()

    visited.add(base_addr)
    valid_chars = set()

    try:
        # Read node data (24 bytes total)
        node_data = binary[base_addr:base_addr + 24]

        # Extract bounds from offset 8 and 9
        lower = node_data[8]
        upper = node_data[9]

        # Add valid characters
        for c in range(lower, upper + 1):
            valid_chars.add(chr(c))

        # Get child pointers (at offset 16 and 24)
        left_child = u64(node_data[16:24])
        right_child = u64(node_data[24:32])

        # Recursively analyze children
        if left_child and left_child != base_addr:
            valid_chars.update(analyze_node(binary, left_child, visited))
        if right_child and right_child != base_addr:
            valid_chars.update(analyze_node(binary, right_child, visited))

    except Exception as e:
        pass

    return valid_chars

def main():
    # Load binary
    elf = ELF('./ctf_files/rabbithole')
    binary_data = elf.get_section('.data')

    # Look for roots array in data section
    root_addrs = []
    for i in range(0, len(binary_data), 8):
        addr = u64(binary_data[i:i+8])
        if addr != 0:
            root_addrs.append(addr)

    print("[+] Analyzing binary search trees...")
    results = []

    # Analyze each root's tree
    for i in range(0x3b):  # 59 positions
        if i < len(root_addrs):
            valid_chars = analyze_node(binary_data, root_addrs[i])
            results.append((i, valid_chars))
        else:
            results.append((i, set()))

    # Analyze and print results
    print("\n[+] Valid characters for each position:")
    print("-" * 60)

    for pos, chars in results:
        chars_list = sorted(list(chars))
        print(f"\nPosition {pos:2d}: {''.join(chars_list)}")

        # Pattern analysis
        chars_set = set(chars_list)

        # Check character types
        types = []
        if chars_set & set(string.ascii_lowercase):
            types.append("lowercase")
        if chars_set & set(string.ascii_uppercase):
            types.append("uppercase")
        if chars_set & set(string.digits):
            types.append("digits")
        if chars_set & set("_{}"):
            types.append("flag chars")
        if chars_set & set("!@#$%^&*()-+="):
            types.append("special")

        print(f"  Types: {', '.join(types)}")

        # Check for small sets
        if len(chars_list) <= 5:
            print(f"  Limited set: {chars_list}")

        # Check for common flag patterns
        if pos == 0 and 'f' in chars_set:
            print("  Possible flag start")
        if pos == 4 and '{' in chars_set:
            print("  Possible flag open")
        if pos >= 0x3a and '}' in chars_set:
            print("  Possible flag end")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import r2pipe
import string

def analyze_node(r2, addr, visited=None):
    if visited is None:
        visited = set()

    if addr in visited or addr == 0:
        return set()

    visited.add(addr)
    valid_chars = set()

    try:
        # Read node structure
        r2.cmd(f's {addr}')
        node_bytes = r2.cmdj('pxj 24')  # Read 24 bytes

        if len(node_bytes) >= 10:
            # Get character bounds
            lower = node_bytes[8]
            upper = node_bytes[9]

            # Add valid characters
            for c in range(lower, upper + 1):
                if 32 <= c <= 126:  # Printable ASCII
                    valid_chars.add(chr(c))

        # Get child pointers
        left_child = int.from_bytes(bytes(node_bytes[16:24]), byteorder='little')
        right_child = int.from_bytes(bytes(node_bytes[24:32]), byteorder='little')

        # Recursively analyze children
        if left_child and left_child != addr:
            valid_chars.update(analyze_node(r2, left_child, visited))
        if right_child and right_child != addr:
            valid_chars.update(analyze_node(r2, right_child, visited))

    except Exception as e:
        pass

    return valid_chars

def main():
    print("[+] Opening binary in radare2...")
    r2 = r2pipe.open("./ctf_files/rabbithole")
    r2.cmd('aaa')  # Analyze all

    print("[+] Finding roots array...")
    roots_section = r2.cmdj('isj')  # Get sections info
    roots_data = None

    # Find roots array in data section
    for section in roots_section:
        if section['name'] == '.data':
            roots_data = r2.cmdj(f'pxj {section["size"]} @ {section["vaddr"]}')
            break

    if not roots_data:
        print("[-] Could not find roots array")
        return

    root_addrs = []
    for i in range(0, len(roots_data), 8):
        addr = int.from_bytes(bytes(roots_data[i:i+8]), byteorder='little')
        if addr != 0:
            root_addrs.append(addr)

    print("[+] Analyzing binary search trees...")
    results = []

    # Analyze each root's tree
    for i in range(0x3b):  # 59 positions
        if i < len(root_addrs):
            valid_chars = analyze_node(r2, root_addrs[i])
            results.append((i, valid_chars))
            print(f"[*] Position {i} analyzed: {len(valid_chars)} valid chars")
        else:
            results.append((i, set()))

    # Analysis and patterns
    print("\n[+] Valid characters for each position:")
    print("-" * 60)

    potential_flag = ['?'] * 0x3b
    for pos, chars in results:
        chars_list = sorted(list(chars))
        print(f"\nPosition {pos:2d}: {''.join(chars_list)}")

        # Pattern analysis
        chars_set = set(chars_list)

        # Character type analysis
        types = []
        if chars_set & set(string.ascii_lowercase):
            types.append("lowercase")
        if chars_set & set(string.ascii_uppercase):
            types.append("uppercase")
        if chars_set & set(string.digits):
            types.append("digits")
        if chars_set & set("_{}"):
            types.append("flag chars")
        if chars_set & set("!@#$%^&*()-+="):
            types.append("special")

        print(f"  Types: {', '.join(types)}")

        # Check for small sets
        if len(chars_list) <= 5:
            print(f"  Limited set: {chars_list}")

        # Flag pattern detection
        if pos == 0 and 'f' in chars_set:
            potential_flag[pos] = 'f'
        elif pos == 1 and 'l' in chars_set:
            potential_flag[pos] = 'l'
        elif pos == 2 and 'a' in chars_set:
            potential_flag[pos] = 'a'
        elif pos == 3 and 'g' in chars_set:
            potential_flag[pos] = 'g'
        elif pos == 4 and '{' in chars_set:
            potential_flag[pos] = '{'
        elif pos == len(potential_flag) - 1 and '}' in chars_set:
            potential_flag[pos] = '}'

    print("\n[+] Potential flag pattern:")
    print(''.join(potential_flag))

if __name__ == '__main__':
    main()
